import{_ as e,o as a,c as r,ah as d}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Billing","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/billing.md","filePath":"src/en/guide/billing.md"}'),n={name:"en/guide/billing.md"};function i(o,t,s,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="billing" tabindex="-1">Billing <a class="header-anchor" href="#billing" aria-label="Permalink to &quot;Billing&quot;">​</a></h1><p>All billing is in <strong>FCFA</strong>, excluding tax, stored as <code>DECIMAL(12,2)</code>. Invoices carry a VAT exemption mention and the payment terms set by the Administrator. They are generated as PDFs, stored privately and emailed to the payer.</p><h2 id="the-30-40-30-schedule" tabindex="-1">The 30/40/30 schedule <a class="header-anchor" href="#the-30-40-30-schedule" aria-label="Permalink to &quot;The 30/40/30 schedule&quot;">​</a></h2><p>Each enrolment produces <strong>three invoices</strong>, on dates calculated by the cohort:</p><table tabindex="0"><thead><tr><th>Instalment</th><th>Share</th><th>Due date</th><th>Issued</th></tr></thead><tbody><tr><td>1</td><td>30%</td><td>Cohort start, or signature if later</td><td>On countersignature of the agreement</td></tr><tr><td>2</td><td>40%</td><td>Mid-course</td><td>15 days before the due date, with the D-15 reminder</td></tr><tr><td>3</td><td>30%</td><td>Cohort end</td><td>15 days before the due date, with the D-15 reminder</td></tr></tbody></table><p>Dates are never entered: the mid-course date and the three due dates are calculated from the cohort dates. References are yearly and readable: <code>FAC-NB-YYYY-XXX</code> for invoices, <code>AV-NB-YYYY-XXX</code> for credit notes.</p><h2 id="shared-funding" tabindex="-1">Shared funding <a class="header-anchor" href="#shared-funding" aria-label="Permalink to &quot;Shared funding&quot;">​</a></h2><p>Before signature, the Coordinator designates a <strong>funder</strong> (organisation account with the Funder role) and its share, from 1 to 100%. The split appears in the agreement.</p><ul><li>Each instalment is billed as <strong>one invoice per payer</strong>: the learner and the funder are tracked separately.</li><li>The funder sees, in their area, the learners they fund and the invoices for their share.</li><li>If the funder is late, the learner&#39;s Sève access is suspended <strong>even if their own share is paid</strong>. Payment restores access.</li></ul><h2 id="collection" tabindex="-1">Collection <a class="header-anchor" href="#collection" aria-label="Permalink to &quot;Collection&quot;">​</a></h2><p>Payments are entered by the Coordinator: amount, method, reference, date. <strong>Partial</strong> payments are allowed. A receipt is sent to the payer.</p><table tabindex="0"><thead><tr><th>Method</th><th>Entry</th></tr></thead><tbody><tr><td>Bank transfer</td><td>Manual</td></tr><tr><td>Cheque</td><td>Manual</td></tr><tr><td>Mobile Money (Flooz, T-Money)</td><td>Manual</td></tr><tr><td>Bank card</td><td>Manual</td></tr><tr><td>Cash</td><td>Manual</td></tr></tbody></table><p>Online payment through <strong>PayGate</strong> (Flooz, T-Money) is planned by ADR-006 but not wired yet: until it is, every payment goes through manual entry.</p><h2 id="reminders" tabindex="-1">Reminders <a class="header-anchor" href="#reminders" aria-label="Permalink to &quot;Reminders&quot;">​</a></h2><table tabindex="0"><thead><tr><th>When</th><th>Event</th><th>Actor</th></tr></thead><tbody><tr><td>D-15, D-7, D-1</td><td>Due-date reminder (email, Sève, WhatsApp)</td><td>Kura</td></tr><tr><td>D+1</td><td>Unpaid due-date reminder</td><td>Kura</td></tr><tr><td>D+7</td><td>Personal follow-up (email or call)</td><td>Pedagogical Coordinator</td></tr><tr><td>D+15</td><td>Invoice <strong>overdue</strong>, start of the automatic <strong>15-day moratorium</strong></td><td>Kura</td></tr><tr><td>D+30</td><td>Without payment, <strong>Sève access suspension</strong></td><td>Kura</td></tr><tr><td>After D+30</td><td>Interview, payment plan, withdrawal if nothing</td><td>Pedagogical Coordinator</td></tr></tbody></table><p>The moratorium is <strong>single and non-negotiable</strong>: it postpones the due date by 15 days and remains visible on the invoice. Payment, at any stage, restores access automatically.</p><p>This timeline replaces the earlier rules (“overdue” at D+1, moratorium on request, suspension at D+15, due date 15 days after issue).</p><h2 id="credit-notes-and-refunds" tabindex="-1">Credit notes and refunds <a class="header-anchor" href="#credit-notes-and-refunds" aria-label="Permalink to &quot;Credit notes and refunds&quot;">​</a></h2><p>A credit note <code>AV-NB-YYYY-XXX</code> carries a type:</p><ul><li><strong>cancellation of the outstanding balance</strong>: unpaid instalments are cancelled;</li><li><strong>refund</strong>: amounts already paid are returned, once the refund is made.</li></ul><p>Main cases:</p><table tabindex="0"><thead><tr><th>Case</th><th>Treatment</th></tr></thead><tbody><tr><td>Cohort change (postponement, force majeure)</td><td>Payments kept; outstanding balance cancelled by credit note; new agreement bills each instalment minus payments</td></tr><tr><td>Cohort cancelled by NextBoxx</td><td>100% refund credit note for amounts paid; refund recorded by the Coordinator</td></tr><tr><td>Voluntary withdrawal</td><td>No credit note; remaining instalments not billed; issued invoices remain due; partial attestation</td></tr><tr><td>Event cancelled</td><td>Credit note for paid registrants; outstanding balance cancelled</td></tr><tr><td>Event registration unpaid at 48 hours</td><td>Credit note for the outstanding balance, seat freed</td></tr></tbody></table><h2 id="invoices-outside-the-schedule" tabindex="-1">Invoices outside the schedule <a class="header-anchor" href="#invoices-outside-the-schedule" aria-label="Permalink to &quot;Invoices outside the schedule&quot;">​</a></h2><p>Only these events invoice outside an enrolment schedule:</p><ul><li>a catch-up or retake request, invoiced immediately;</li><li>registration to a paid event;</li><li>an accepted B2B quote;</li><li>a confirmed matching or support engagement.</li></ul><p>Any other invoice is validated by the Coordinator.</p><p>Event invoices have no training enrolment, agreement or instalment. They are due 48 hours before the event starts and excluded from the billing calendar, training reminders, commissions and dashboards.</p><h2 id="remuneration-and-commissions" tabindex="-1">Remuneration and commissions <a class="header-anchor" href="#remuneration-and-commissions" aria-label="Permalink to &quot;Remuneration and commissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Beneficiary</th><th>Calculation basis</th><th>Payment</th></tr></thead><tbody><tr><td>Lead Trainer</td><td>Programme hours × hourly rate for the zone, + project flat fee</td><td>Approved by the Coordinator, paid outside Kura</td></tr><tr><td>Coach-Tutor</td><td>Headcount at start × coach flat fee, shared between co-coaches</td><td>Same</td></tr><tr><td>External jury</td><td>Token due for actually holding the defence</td><td>Same</td></tr><tr><td>Business referrer</td><td>5% of each payment collected, including the funder&#39;s share</td><td>Same; negative line on refund</td></tr><tr><td>Marketing partner</td><td>Invoice submitted, within the contract or flat fee</td><td>Approved or rejected with a reason, then paid</td></tr></tbody></table><p>A cohort keeps the rates and zone of its <strong>start</strong>, even if a learner later withdraws. Calculated amounts can be adjusted by the Coordinator before approval; the payment is always recorded afterwards, because it happens outside Kura.</p><h2 id="financial-indicators" tabindex="-1">Financial indicators <a class="header-anchor" href="#financial-indicators" aria-label="Permalink to &quot;Financial indicators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Indicator</th><th>Definition</th></tr></thead><tbody><tr><td>Invoiced</td><td>Sum of invoices, net of cancellation credit notes</td></tr><tr><td>Collected</td><td>Sum of payments, net of refunds</td></tr><tr><td>Outstanding</td><td>Invoiced − collected, including the overdue part</td></tr><tr><td>Paid out</td><td>Remuneration and commissions paid, plus paid marketing invoices</td></tr><tr><td>Gross margin</td><td>Collected − paid out</td></tr></tbody></table><p>The Direction view adds paid out and gross margin; reporting stops at outstanding. Both views exclude event invoices.</p><h2 id="good-practices" tabindex="-1">Good practices <a class="header-anchor" href="#good-practices" aria-label="Permalink to &quot;Good practices&quot;">​</a></h2><ul><li>Record a payment <strong>in a transaction</strong> and check the balance after locking the row, to avoid overpayment when entries are simultaneous.</li><li>Never issue an invoice without checking that none already exists for the same agreement, payer and instalment.</li><li>Keep the PDFs and their fingerprints: an issued invoice is not reissued, it is corrected by a credit note.</li></ul>',35)])])}const p=e(n,[["render",i]]);export{m as __pageData,p as default};
